import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    x = torch.empty(shape, dtype=dtype, device=device).uniform_(-0.9, 0.9)
    return {"x": x}


@torch.no_grad()
def run(x):
    return torch.ops.aten.special_erfinv(x)


def run_correctness(x):
    output = torch.ops.aten.special_erfinv(x.float())
    return output.to(x.dtype)
